INSERT INTO `dynamic_pages` (`id`, `menu_id`, `slug`, `title`, `template`, `content`, `hero_badge`, `meta_title`, `meta_desc`, `published`, `created_at`, `updated_at`) VALUES
(1, NULL, 'visi-misi', 'Visi & Misi', 'penjelasan_2', '{\"subtitle\":\"Konten hasil migrasi dari website lama.\",\"box_1_title\":\"Visi\",\"box_1_content\":\"<p>\\u201cMembangun Mahulu Untuk Semua : Sejahtera Berkeadilan\\u201d<\\/p>\",\"box_2_title\":\"Misi\",\"box_2_content\":\"<p>\\u201cMenciptakan tata pemerintahan yang bersih, berwibawa, transparan, dan\\nakuntabel\\u201d<\\/p>\"}', NULL, 'Visi & Misi', 'Konten hasil migrasi dari website lama.', 1, '2026-05-10 01:08:48', '2026-05-10 01:20:51'),
(2, NULL, 'tujuan-sasaran', 'Tujuan & Sasaran', 'penjelasan_2', '{\"subtitle\":\"Konten hasil migrasi dari website lama.\",\"box_1_title\":\"Tujuan\",\"box_1_content\":\"<p>Meningkatkan Kualitas Perencanaan,\\nPenelitian dan Pengendalian\\nPembangunan yang akuntabel<\\/p>\",\"box_2_title\":\"Sasaran\",\"box_2_content\":\"<p>Meningkatkan Keselarasan Perencanaan Pembangunan. Meningkatnya kualitas perencanaan pada (Bidang Perekonomian dan SDA, Bidang PPM dan Bidang Infrastruktur &amp; Kewilayahan). Meningkatkan Peran Kelitbangan Dalam Pembangunan<\\/p>\"}', NULL, 'Tujuan & Sasaran', 'Konten hasil migrasi dari website lama.', 1, '2026-05-10 01:08:48', '2026-05-10 01:20:51'),
(3, NULL, 'motto', 'Motto & Maklumat Pelayanan', 'penjelasan_2', '{\"subtitle\":\"Konten hasil migrasi dari website lama.\",\"box_1_title\":\"Motto\",\"box_1_content\":\"<p>&quot;Berhasil membuat perencanaan, berarti merencanakan keberhasilan&quot;<\\/p>\",\"box_2_title\":\"Maklumat Pelayanan\",\"box_2_content\":\"<p>1. Sanggup menyelenggarakan pelayanan sesuai standar pelayanan yang telah di tetapkan\\n2. Akan melakukan perbaikan pelayanan secara berkelanjutan dan\\n3. Apabila tidak menepati janji, kami akan siap menerima sanksi sesuai peraturan perundang - undangan yang berlaku<\\/p>\"}', NULL, 'Motto & Maklumat Pelayanan', 'Konten hasil migrasi dari website lama.', 1, '2026-05-10 01:08:50', '2026-05-10 01:20:53'),
(4, NULL, 'struktur', 'Struktur Organisasi', 'penjelasan_1', '{\"judul\":\"Struktur Organisasi\",\"isi_konten\":\"<p><img src=\\\"https://bappelitbangdamahulu.com/assets/struktur_organisasi2.png\\\" alt=\\\"Struktur Organisasi\\\"></p>\"}', NULL, 'Struktur Organisasi', 'Struktur Organisasi Bagian Protokol dan Komunikasi Pimpinan (PROKOPIM) Kabupaten Mahakam Ulu.', 1, '2026-05-10 01:08:51', '2026-10-30 10:24:28'),
(5, NULL, 'tupoksi', 'Tupoksi', 'penjelasan_2', '{\"subtitle\":\"Konten hasil migrasi dari website lama.\",\"box_1_title\":\"Tugas Pokok\",\"box_1_content\":\"<p>Badan Perencanaan Pembangunan Penelitian dan Pengembangan Daerah mempunyai tugas membantu gubernur melaksanakan Urusan penunjang Pemerintahan di bidang perencanaan, penelitian dan pengembangan.<\\/p>\",\"box_2_title\":\"Fungsi\",\"box_2_content\":\"<p>a) Perumusan kebijakan daerah di bidang Perencanaan Pembangunan, Penelitian dan Pengembangan Daerah;\\nb) Penetapan kebijakan teknis di bidang Perencanaan Pembangunan, Penelitian dan Pengembangan Daerah;\\nc) Penyelenggaraan, Pengkoordinasikan, dan Sinkronisasi perumusan program dan kegiatan di bidang Perencanaan Pembangunan, Penelitian dan Pengembangan Daerah;\\nd) Penyelenggaraan tugas dukungan teknis di bidang Perencanaan Pembangunan, Penelitian dan Pengembangan Daerah\\ne) Penyelenggaraan Pengendalian, Evaluasi dan Pelaporan pelaksanaan tugas dukungan teknis di bidang Perencanaan Pembangunan, Penelitian dan Pengembangan Daerah; f) Penyelenggaraan Fungsi Kesekretariatan Badan Perencanaan Pembangunan, Penelitian dan Pengembangan Daerah; \\ng) Pelaksanaan fungsi lain yang diberikan oleh Bupati sesuai dengan tugas dan fungsinya<\\/p>\"}', NULL, 'Tupoksi', 'Konten hasil migrasi dari website lama.', 1, '2026-05-10 01:19:42', '2026-05-10 01:20:52'),
(7, 35, 'undang-undang', 'Undang Undang', 'dokumen_list', '{\"mode\":\"automatic\",\"ppid_id\":33}', 'Dokumen Publik', 'Undang Undang', 'Halaman dokumen terhubung otomatis ke data PPID.', 1, '2026-06-01 19:10:32', '2026-07-29 18:26:53'),
