-- Dumping data untuk tabel `posts`
--

INSERT INTO `posts` (`id`, `user_id`, `category_id`, `title`, `slug`, `content`, `attachments`, `attachment_names`, `tags`, `type`, `status`, `show_on_home`, `seo`, `read`, `penulis`, `published_at`, `sort_order`, `file_id`, `created_at`, `updated_at`) VALUES
(128, 1, 1, 'Bupati Mahulu Dorong KBMKMU Kaltim Jadi Ruang Pengembangan Kapasitas Mahasiswa', 'bupati-mahulu-dorong-kbmkmu-kaltim-jadi-ruang-pengembangan-kapasitas-mahasiswa', '<p>Samarinda – Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan, menekankan pentingnya integritas, tanggung jawab dan solidaritas mahasiswa sebagai bagian dari proses menyiapkan generasi muda yang mampu berkontribusi bagi kemajuan Mahakam Ulu.</p>\n<p>Pesan tersebut disampaikan Bupati saat menghadiri Pelantikan Pengurus Keluarga Besar Mahasiswa Kabupaten Mahakam Ulu Kalimantan Timur (KBMKMU Kaltim) Periode 2026–2028 di Gedung Aula Bina Warga, Samarinda. Senin (31/08/2026)</p>\n<p>Bupati menyampaikan selamat kepada Ketua Umum KBMKMU Kaltim, Nikolas Fernando beserta seluruh pengurus yang telah dilantik. Ia berharap kepercayaan yang diberikan mahasiswa dapat dijawab melalui kerja organisasi yang berintegritas, bertanggung jawab dan memberi manfaat bagi seluruh anggota.</p>\n<p>“Bagaimana kita mengemban tanggung jawab, bagaimana kita membawa Mahakam Ulu menjadi lebih baik, menjadi satu kabupaten yang jauh lebih maju. Semua itu dimulai dari organisasi ini, semua itu dimulai dari adik-adik yang sedang menempuh pendidikan,” tegasnya.</p>\n<p>Menurut Bupati, KBMKMU Kaltim harus menjadi rumah bersama bagi mahasiswa Mahulu, bukan sekadar wadah berkumpul. Organisasi perlu hadir untuk membantu mahasiswa beradaptasi dengan lingkungan perkuliahan dan kehidupan di kota, khususnya bagi mahasiswa baru yang masih menghadapi berbagai keterbatasan.</p>\n<p>Karena itu, Bupati minta mahasiswa senior untuk mengayomi dan merangkul mahasiswa baru yang masih mengalami kesulitan dalam beradaptasi, baik dalam penggunaan teknologi, komunikasi maupun membangun pergaulan.</p>\n<p>“Jangan berjalan sendiri, tetapi bergandeng tanganlah. Kita bangun solidaritas sebagai satu Mahakam Ulu, bukan berdasarkan kecamatan tertentu,” pesannya.</p>\n<p>Angela Idang Belawan juga mendorong mahasiswa untuk tidak minder dan berani mengembangkan potensi yang dimiliki.</p>\n<p>Menurutnya, mahasiswa Mahulu harus mampu mempersiapkan diri agar dapat bersaing dalam berbagai kesempatan, termasuk dalam dunia kerja maupun seleksi aparatur sipil negara.</p>\n<p>“Persiapkan diri dengan matang. Setiap hari adalah belajar untuk kita,” ujarnya.</p>\n<p>Untuk itu, KBMKMU Kaltim didorong menjadi ruang pengembangan kapasitas melalui forum diskusi, pelatihan organisasi, kelompok belajar serta kegiatan yang membuka jejaring dan kesempatan bagi mahasiswa untuk berkembang.</p>\n<p>Bupati menegaskan, mahasiswa Mahulu harus mampu menjaga nama baik daerah melalui sikap, prestasi dan tanggung jawab.</p>\n<p>Pendidikan, menurutnya, bukan hanya tentang memperoleh ilmu di bangku kuliah, tetapi juga membangun pengalaman, jejaring dan karakter sebagai bekal untuk kembali mengambil bagian dalam pembangunan daerah. Pemerintah Kabupaten Mahakam Ulu, lanjutnya, siap mendengarkan dan memberikan dukungan sesuai kemampuan.</p>\n<p>Namun, mahasiswa juga diminta tetap mandiri dan tidak menjadikan bantuan sebagai alasan untuk bergantung.</p>\n<p>Menutup arahannya, Bupati menitipkan dua prinsip utama kepada seluruh mahasiswa, yakni kejujuran dan tanggung jawab.</p>\n<p>“Jaga kejujuran dan tanggung jawab. Itu kunci kesuksesan yang akan membawa saudara-saudari mencapai cita-cita,” pungkasnya.</p>\n<p>Pelantikan turut dihadiri Penasehat KBMKMU Kaltim, Anastasia Hiyang, S.IP., M.Si., Kepala Dinas Pendidikan dan Kebudayaan Mahulu, Samson Batang, S.Sos., M.Si., Wakil Dekan Kemahasiswaan, Alumni dan Kerjasama, FISIP Universitas Mulawarman, Daryono, S.Sos., M.Si., Ph.D.; Ketua Kwarcab Pramuka Mahulu, Martinus Jeno, Ketua LPADKT, A Vendy Meru, Ketua Panitia Marvin Dimas Awang Kuwai, serta pengurus lama dan alumni KBMKMU Kaltim. (Prokopim/tha)</p>\n<p>Berita TerkiniBidang Pemerintahan dan Kesejahteraan RakyatPembinaanPendidikan</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangPemerintahandanKesejahteraanRakyat\"]', 'post', 1, 0, NULL, 123, 'Adm', '2026-08-31 00:00:00', 0, 159, '2026-09-02 08:13:54', '2026-10-30 07:22:20'),
(129, 1, 1, 'Pemkab Mahulu Perkuat Koordinasi Pembukaan Akses Darat Menuju Long Apari', 'pemkab-mahulu-perkuat-koordinasi-pembukaan-akses-darat-menuju-long-apari', '<p>Long Apari – Pemerintah Kabupaten (Pemkab) Mahakam Ulu (Mahulu) terus mengupayakan pembukaan akses darat menuju Kecamatan Long Apari sebagai langkah jangka panjang untuk memperlancar distribusi logistik dan kebutuhan masyarakat di wilayah tersebut.</p>\n<p>Hal itu disampaikan Wakil Bupati Mahulu Suhuk, S.E., saat menyalurkan bantuan di Kecamatan Long Apari, pada hari Minggu (30/8/2026). Menurutnya, pembukaan akses darat menjadi kebutuhan penting, terutama di tengah kondisi kemarau yang menyebabkan distribusi bantuan dan logistik menghadapi berbagai keterbatasan.</p>\n<p>Suhuk menyampaikan, berdasarkan informasi terakhir, dukungan alat berat untuk pembukaan akses telah bergerak menuju kawasan Gunung Waterboom. Masih terdapat sekitar 20 kilometer akses yang perlu dibuka untuk mendukung keterhubungan menuju wilayah Long Apari.</p>\n<p>“Mudah-mudahan dengan bantuan alat dari provinsi dan kita dari kabupaten mensubsidi untuk BBM-nya, penyaluran logistik nanti tidak lagi menggunakan transportasi air, tetapi bisa lewat darat,” ujar Suhuk.</p>\n<p>Ia menjelaskan, pembukaan akses darat tidak hanya akan memperlancar mobilitas masyarakat, tetapi juga membantu menekan biaya distribusi bantuan. Selama ini, penggunaan jalur air membutuhkan biaya yang cukup besar, sehingga sebagian anggaran yang seharusnya dapat dimanfaatkan untuk pemenuhan kebutuhan masyarakat harus dialokasikan untuk transportasi.</p>\n<p>“Kalau lewat jalur air, cost-nya cukup besar. Yang seharusnya mungkin bisa dipakai untuk ketahanan pangan dan memenuhi bantuan lagi, banyak terkuras di biaya transportasi,” jelasnya.</p>\n<p>Karena itu, Pemkab Mahulu terus memperkuat koordinasi dengan Pemerintah Provinsi Kalimantan Timur dalam mendukung percepatan pembukaan akses tersebut, termasuk dukungan alat berat dan kebutuhan operasionalnya.</p>\n<p>Wabup berharap seluruh pihak dapat bersinergi sesuai peran masing-masing sehingga pembukaan akses dapat berjalan secara bertahap dan memberikan manfaat bagi masyarakat.</p>\n<p>“Kita terus mengusahakan jalan ini. Harapannya, akses darat dapat segera terbuka sehingga ke depan distribusi logistik kepada masyarakat Long Apari menjadi lebih efektif dan tidak terlalu bergantung pada jalur air,” pungkasnya.</p>\n<p>Pembukaan akses darat tersebut menjadi bagian dari komitmen jangka panjang Pemerintah Kabupaten Mahulu dalam mengurangi keterisolasian wilayah sekaligus memperkuat konektivitas dan pemerataan pembangunan hingga ke wilayah paling hulu.(Prokopim/vta)</p>\n<p>Berita TerkiniBidang Ekonomi dan PembangunanPembangunanPenanggulangan BencanaPerhubungan</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangEkonomidanPembangunan\"]', 'post', 1, 0, NULL, 121, 'Adm', '2026-08-30 00:00:00', 0, 160, '2026-09-02 08:13:54', '2026-10-30 15:13:37'),
(130, 1, 1, 'Tiba di Long Apari, Wabup Mahulu Serahkan Bantuan Untuk Warga Terdampak Kemarau', 'tiba-di-long-apari-wabup-mahulu-serahkan-bantuan-untuk-warga-terdampak-kemarau', '<p>Long Apari – Mewakili Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan, Wakil Bupati (Wabup) Mahulu, Suhuk, S.E., tiba di Kecamatan Long Apari, Minggu (30/8/2026), dan langsung menyalurkan bantuan kepada masyarakat terdampak kemarau panjang, di Dermaga Dermaga Kecamatan Long Apari.</p>\n<p>Kedatangan Wabup bersama rombongan merupakan bagian dari upaya Pemerintah Kabupaten Mahulu memastikan bantuan dapat menjangkau masyarakat di wilayah paling hulu yang menghadapi dampak kemarau serta keterbatasan akses transportasi.</p>\n<p>Atas nama Pemerintah Kabupaten Mahulu, Suhuk menyampaikan apresiasi dan terima kasih kepada Pemerintah Provinsi Kalimantan Timur yang telah memberikan dukungan dalam penanganan dampak kemarau di Kecamatan Long Pahangai dan Long Apari.</p>\n<p>Menurutnya, Pemprov Kaltim telah menyiapkan bantuan sekitar 69 ton untuk masyarakat terdampak. Pemkab Mahulu kemudian berinisiatif membantu mengangkut bantuan tersebut agar dapat diteruskan hingga ke wilayah penerima.</p>\n<p>“Kalau mereka tidak punya anggaran untuk membawa kesini, kita dari Kabupaten Mahakam Ulu akan jemput untuk mengantarkan. Karena bantuan kadang hanya sampai di ibu kota, sehingga kita harus antar lagi ke kampung-kampung,” ujar Suhuk.</p>\n<p>Suhuk berharap bantuan tersebut dapat meringankan beban masyarakat Long Apari. Meski belum sepenuhnya mencukupi kebutuhan seluruh masyarakat, pemerintah akan terus mencari dukungan dan peluang bantuan bagi masyarakat di wilayah terpencil.</p>\n<p>Ia juga mengajak masyarakat untuk tetap tenang, saling membantu dan menjaga kebersamaan dalam menghadapi kondisi kemarau.</p>\n<p>“Kekuatan kita adalah gotong royong dan kepedulian terhadap sesama. Semoga ini dapat menjadi bukti kehadiran pemerintah kepada masyarakat,” katanya.</p>\n<p>Dalam proses penyaluran, Suhuk meminta seluruh pihak yang terlibat untuk menjaga ketertiban dan memastikan bantuan diterima oleh masyarakat yang benar-benar membutuhkan. Ia juga menekankan pentingnya verifikasi dan pemutakhiran data penerima agar penyaluran berlangsung transparan, adil dan tepat sasaran.</p>\n<p>“Harapan saya, data-data yang ada dapat terus ditertibkan dan dikroscek bersama agar penyaluran yang kita lakukan tetap transparan, adil, tepat sasaran, serta dapat dipertanggungjawabkan,” tegasnya.(Prokopim/vta)</p>\n<p>Bantuan SosialBerita TerkiniBidang Pemerintahan dan Kesejahteraan RakyatPenanggulangan BencanaSosial</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BantuanSosial\",\"BeritaTerkini\"]', 'post', 1, 0, NULL, 107, 'Adm', '2026-08-30 00:00:00', 0, 161, '2026-09-02 08:13:54', '2026-10-29 21:08:52'),
(131, 1, 1, 'Kemarau Panjang, Pemkab Mahulu Salurkan Bantuan ke Long Pahangai dan Long Apari', 'kemarau-panjang-pemkab-mahulu-salurkan-bantuan-ke-long-pahangai-dan-long-apari', '<p>Ujoh Bilang – Mewakili Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan, Wakil Bupati (Wabup) Mahulu, Suhuk, S.E., melepas rombongan pengiriman bantuan bagi masyarakat terdampak bencana akibat kemarau panjang di Kecamatan Long Pahangai dan Long Apari, Kabupaten Mahakam Ulu yang berkumpul di Kantor Bupati Mahulu, Sabtu (29/08/26).</p>\n<p>Bantuan tersebut merupakan bentuk kepedulian dan dukungan dalam membantu masyarakat yang terdampak kondisi kemarau panjang yang terjadi di sejumlah wilayah Mahulu.</p>\n<p>Dalam penyaluran bantuan ini, Badan Penanggulangan Bencana Daerah (BPBD) Kabupaten Mahulu mengirimkan bantuan pangan sebanyak 7 ton. Sementara itu, Bank BPD Kaltimtara turut memberikan 555 paket bantuan yang terdiri atas beras, minyak goreng, dan gula.</p>\n<p>Selain bantuan pangan, dukungan juga diberikan melalui alat kesehatan dan obat-obatan dari Dinas Kesehatan, Pengendalian Penduduk dan Keluarga Berencana (Dinkes P2KB) Kabupaten Mahulu. Bantuan tersebut diharapkan dapat mendukung kebutuhan masyarakat, khususnya dalam menghadapi kondisi kemarau panjang.</p>\n<p>Dalam kesempatan tersebut, Suhuk menyampaikan apresiasi kepada Bank BPD Kaltimtara yang terus memberikan dukungan kepada Pemerintah Kabupaten Mahulu dalam menghadapi kondisi kemarau yang berdampak terhadap masyarakat.</p>\n<p>“Atas nama Kabupaten Mahakam Ulu, saya mengucapkan terima kasih atas bantuan yang diberikan oleh Bank BPD yang terus mensupport kita dalam menghadapi kemarau ini,” ujar Suhuk.</p>\n<p>Ia juga menyampaikan terima kasih kepada seluruh pihak dan rombongan yang turut mengambil bagian dalam proses pengiriman dan penyaluran bantuan kepada masyarakat di wilayah terdampak.</p>\n<p>“Saya ucapkan juga terima kasih kepada rombongan semua yang boleh mengambil bagian dalam penyaluran bantuan ini. Kiranya Tuhan yang akan menolong kita, khususnya dalam perjalanan, sehingga kita boleh berangkat dan boleh kembali ke tempat ini dengan berkat pertolongan Tuhan,” katanya.</p>\n<p>Menurut Wakil Bupati, keterlibatan berbagai pihak dalam membantu masyarakat yang terdampak bencana merupakan bentuk kepedulian dan solidaritas yang sangat berarti, terlebih dalam menghadapi kondisi kemarau panjang.</p>\n<p>Ia berharap bantuan yang disalurkan dapat memberikan manfaat dan meringankan beban masyarakat di Kecamatan Long Pahangai dan Long Apari.</p>\n<p>“Apa yang kita lakukan, yakinlah, percayalah akan menjadi berkat bagi kita ke depannya,” pungkasnya.</p>\n<p>Pemerintah Kabupaten Mahakam Ulu terus mendorong sinergi dan kepedulian bersama dari berbagai pihak dalam menghadapi dampak kemarau panjang, sekaligus memastikan kebutuhan masyarakat di wilayah terdampak tetap mendapatkan perhatian.(Prokopim/vta)</p>\n<p>Bantuan SosialBerita TerkiniPemerintahanSosial</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BantuanSosial\",\"BeritaTerkini\"]', 'post', 1, 0, NULL, 139, 'Admin', '2026-08-29 00:00:00', 0, 162, '2026-09-02 08:13:54', '2026-10-29 22:05:33'),
(132, 1, 1, 'Bupati Mahulu Dorong Perencanaan Pembangunan Lebih Tepat Sasaran dan Berdampak Bagi Masyarakat', 'bupati-mahulu-dorong-perencanaan-pembangunan-lebih-tepat-sasaran-dan-berdampak-bagi-masyarakat', '<p>Jakarta – Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan mengikuti Sosialisasi dan Pendampingan Manajemen Kinerja Pemerintah Daerah yang diselenggarakan Badan Perencanaan, Penelitian dan Pengembangan Daerah (Bappelitbangda) Kabupaten Mahulu bekerja sama dengan Universitas Negeri Surabaya (UNESA), di Jakarta, Jumat (28/08/2026).</p>\n<p>Kegiatan tersebut membahas penyusunan Pohon Kinerja (POKIN) sebagai bagian dari upaya meningkatkan tata kelola pemerintahan serta memastikan program pembangunan daerah berjalan sesuai visi dan misi kepala daerah.</p>\n<p>Dalam kesempatan tersebut, Bupati Angela menekankan pentingnya penyusunan kinerja pemerintah yang tidak sekadar menjadi rutinitas tahunan, tetapi mampu memberikan manfaat nyata bagi masyarakat.</p>\n<p>“Saya rasa kegiatan di Pohon Kinerja ini mirip dengan presensi yang sudah di buat. Kenapa saya bilang mirip Pertama, yang jelas yang ingin kita capai untuk meningkatkan kedisiplinan,” ujar Angela.</p>\n<p>Menurutnya, pemerintah daerah harus mampu menerjemahkan visi dan misi yang tertuang dalam Rencana Pembangunan Jangka Menengah Daerah (RPJMD) ke dalam program dan kegiatan yang memiliki dampak nyata bagi masyarakat.</p>\n<p>“Karena itu, saya berharap besar dari penjabaran RPJMD, visi dan misi yang saya tuangkan. Bukan masalah bagaimana anggaran. Anggaran kita sediakan, silahkan dilaksanakan,” katanya.</p>\n<p>Angela menegaskan, keterbatasan anggaran tidak boleh menjadi alasan bagi pemerintah untuk tidak menghadirkan manfaat bagi masyarakat. Sebaliknya, setiap program harus mempertimbangkan efektivitas, manfaat, serta potensi yang dimiliki daerah.</p>\n<p>“Saya selalu mengatakan satu: saat ini yang kita butuhkan, dengan anggaran yang minimal, apa yang bisa kita berikan untuk masyarakat kita? Apa yang bisa kita buat dan apa manfaatnya?” tegasnya.</p>\n<p>Sementara itu, Kepala Bappelitbangda Yohanes Andi Abeh, S.Sos., M.Si., menjelaskan bahwa sosialisasi dan pendampingan tersebut difokuskan pada penyusunan Pohon Kinerja (POKIN) serta Rencana Strategis (Renstra) perangkat daerah.</p>\n<p>“Proses penyusunan telah berjalan mulai dari tahap awal hingga sosialisasi kepada perangkat daerah. Namun, masih diperlukan pendampingan secara intensif untuk memastikan proses penyelesaian berjalan optimal, khususnya dalam penyusunan Renstra,” jelasnya.</p>\n<p>Pendampingan tersebut diharapkan dapat memperkuat keterkaitan antara perencanaan, pelaksanaan program, indikator kinerja, serta pencapaian target pembangunan daerah sesuai arah kebijakan dalam RPJMD Kabupaten Mahulu.</p>\n<p>Turut hadir dalam kegiatan tersebut, Sekretaris Daerah Mahulu, Dr. Stephanus Madang, S.Sos., M.M., Kepala Bappelitbangda Pemkab Mahulu Yohanes Andy Abeh, S.Sos., M.Si., dan tim dari Unesa serta jajaran Bappelitbangda. (Prokopim/aim)</p>\n<p>Berita TerkiniBidang Ekonomi dan PembangunanBidang Pemerintahan dan Kesejahteraan RakyatKerja SamaPembangunanPembinaanPemerintahan</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangEkonomidanPembangunan\"]', 'post', 1, 0, NULL, 126, 'Admin', '2026-08-28 00:00:00', 0, 163, '2026-09-02 08:13:54', '2026-10-29 12:00:42'),
(133, 1, 1, 'Pemkab Mahulu dan BRMP Bersinergi Kembangkan Potensi Pertanian Daerah Mahakam Ulu', 'pemkab-mahulu-dan-brmp-bersinergi-kembangkan-potensi-pertanian-daerah-mahakam-ulu', '<p>Jakarta – Kehadiran Pemerintah Kabupaten (Pemkab) Mahakam Ulu (Mahulu) di Badan Perakitan dan Modernisasi Pertanian (BRMP) Kementerian Pertanian membawa harapan besar untuk mengembangkan potensi pertanian daerah melalui dukungan pengetahuan, teknologi, dan pendampingan yang tepat.</p>\n<p>Hal tersebut disampaikan Bupati Mahulu, Angela Idang Belawan dalam kegiatan penandatanganan Nota Kesepahaman (MoU) tentang kerja sama pembangunan dan pengembangan inovasi pertanian bersama Kepala BRMP Kementerian Pertanian, di Ruang Rapat Kantor BRMP, Jakarta, Kamis (27/8/2026).</p>\n<p>Angela mengatakan, Mahakam Ulu memiliki potensi pertanian yang besar untuk terus dikembangkan. Sektor pertanian tidak hanya menjadi bagian penting dalam kehidupan masyarakat, tetapi juga memiliki peluang besar dalam memperkuat perekonomian daerah serta meningkatkan kesejahteraan petani.</p>\n<p>“Mahakam Ulu memiliki potensi pertanian yang besar untuk terus dikembangkan. Sektor ini menjadi bagian penting dalam kehidupan masyarakat sekaligus membuka peluang untuk memperkuat perekonomian daerah dan meningkatkan kesejahteraan petani,” ujar Angela.</p>\n<p>Menurutnya, pengembangan pertanian di Mahakam Ulu harus tetap memperhatikan kondisi wilayah, potensi lokal, serta kearifan masyarakat setempat.</p>\n<p>“Kami ingin pertanian Mahakam Ulu berkembang dengan tetap memperhatikan kondisi wilayah, potensi lokal, dan kearifan masyarakat. Dukungan BRMP kami harapkan dapat membantu masyarakat mengelola potensi tersebut secara lebih baik serta memperoleh hasil yang semakin bernilai,” katanya.</p>\n<p>Angela menambahkan, melalui kerja sama tersebut diharapkan terbuka ruang pembelajaran dan peningkatan kapasitas bagi aparatur, penyuluh, pengelola, maupun petani.</p>\n<p>Pengetahuan serta teknologi yang diperoleh nantinya diharapkan tidak berhenti pada pelaksanaan program, tetapi dapat diterapkan dan diteruskan kepada kelompok tani serta masyarakat di berbagai wilayah Mahakam Ulu.</p>\n<p>“Bagi kami, ukuran keberhasilan kerja sama ini adalah manfaat yang dirasakan masyarakat. Pertanian harus semakin produktif, produk lokal memiliki daya saing, dan petani memperoleh peluang yang lebih luas untuk meningkatkan kesejahteraan keluarganya,” tegasnya.</p>\n<p>Di akhir sambutannya, Angela menyampaikan apresiasi dan terima kasih kepada BRMP Kementerian Pertanian serta seluruh pihak yang telah mempersiapkan kerja sama tersebut.</p>\n<p>“Semoga sinergi yang kita bangun hari ini menjadi langkah bersama yang konsisten dan memberikan hasil nyata bagi kemajuan pertanian serta kesejahteraan masyarakat Kabupaten Mahakam Ulu,” pungkasnya. (Prokopim/aim)</p>\n<p>Berita TerkiniBidang Ekonomi dan PembangunanKerja SamaPertanian</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangEkonomidanPembangunan\"]', 'post', 1, 0, NULL, 124, 'Adm', '2026-08-27 00:00:00', 0, 164, '2026-09-02 08:13:54', '2026-10-30 14:11:44'),
(134, 1, 1, 'Bupati Mahulu Teken MoU Bersama BRMP Kementan, Dorong Pengembangan Inovasi Pertanian', 'bupati-mahulu-teken-mou-bersama-brmp-kementan-dorong-pengembangan-inovasi-pertanian', '<p>Jakarta – Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan menandatangani Nota Kesepahaman (MoU) kerja sama pembangunan dan pengembangan inovasi pertanian bersama Kepala Badan Perakitan dan Modernisasi Pertanian (BRMP) Kementerian Pertanian, Prof. Dr. Ir. Fadjry Djufry, M.Si., di Ruang Rapat Kantor BRMP, Jakarta, Kamis (27/8/2026) pagi.</p>\n<p>Penandatanganan kerja sama tersebut menjadi langkah strategis Pemerintah Kabupaten Mahulu dalam mendorong pengembangan sektor pertanian melalui pemanfaatan inovasi, teknologi, serta potensi daerah.</p>\n<p>Dalam sambutannya, Bupati mengatakan, kerja sama tersebut merupakan bagian dari upaya Pemkab Mahulu untuk membuka jalan bagi kemajuan daerah, khususnya dalam meningkatkan sektor pertanian.</p>\n<p>“Melalui kerja sama ini terdapat harapan masyarakat, terutama para petani dan keluarga yang menggantungkan penghidupan pada sektor pertanian,” ujar Bupati.</p>\n<p>Ia menegaskan, Pemkab Mahulu berkomitmen mengembangkan setiap potensi daerah secara sungguh-sungguh dan berkelanjutan.</p>\n<p>“Melalui kerja sama ini, kami berharap semakin banyak peluang yang dapat dibuka untuk meningkatkan produktivitas, memperkuat perekonomian masyarakat, dan mendorong kesejahteraan yang lebih merata,” lanjutnya.</p>\n<p>Menurut Angela Idang Belawan, sinergi antara Pemkab Mahulu dan BRMP diharapkan dapat semakin diperkuat dalam mengembangkan sektor pertanian yang sesuai dengan potensi dan karakteristik wilayah Mahulu.</p>\n<p>“Keahlian, pengalaman, serta dukungan teknologi dari BRMP akan menjadi kekuatan penting yang dipadukan dengan sumber daya dan pengetahuan lokal yang dimiliki Mahulu,” katanya.</p>\n<p>Sementara itu, Kepala BRMP Kementerian Pertanian, Prof. Dr. Ir. Fadjry Djufry, M.Si., menyambut baik kerja sama tersebut. Ia menilai kolaborasi antara pemerintah daerah dan BRMP dapat menjadi kekuatan dalam mengoptimalkan potensi pertanian di daerah.</p>\n<p>Ia juga mengatakan, BRMP memiliki tugas untuk mendampingi dan mendorong percepatan pembangunan pertanian di berbagai daerah di Indonesia.</p>\n<p>“Bupati dan jajaran datang ke kantor yang tepat, karena kami memang disiapkan untuk melayani seluruh Indonesia. Kami diminta untuk mendampingi dan berakselerasi bersama pimpinan daerah untuk menggerakkan pertanian di seluruh wilayah Indonesia,” jelasnya.</p>\n<p>Karena itu, Ia berharap kerja sama ini dapat menjadi langkah awal untuk mengoptimalkan potensi pertanian Mahulu melalui penerapan teknologi dan inovasi yang sesuai dengan kondisi daerah.</p>\n<p>Turut mendampingi Bupati Mahulu dalam kegiatan tersebut, Sekretaris Daerah Mahulu, Dr. Stephanus Madang, S.Sos., M.M., Kepala Bappelitbangda Pemkab Mahulu Yohanes Andy Abeh, S.Sos., M.Si., Kepala Dinas Ketahanan Pangan dan Pertanian (DKPP) Kabupaten Mahulu Engelbertus Ibrahim, S.E., M.Si., serta sejumlah kepala bagian dan jajaran terkait di lingkungan Pemerintah Kabupaten Mahulu, serta jajaran BRMP. (Prokopim/aim)</p>\n<p>Berita TerkiniBidang Ekonomi dan PembangunanKerja SamaPertanian</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangEkonomidanPembangunan\"]', 'post', 1, 0, NULL, 123, 'Adm', '2026-08-27 00:00:00', 0, 165, '2026-09-02 08:13:54', '2026-10-30 14:02:54'),
(135, 1, 1, 'Pengumuman Hasil 3 (Tiga) Calon Terbaik Seleksi Terbuka Pengisian Jabatan Pimpinan Tinggi Pratama Di Lingkungan Pemerintah Kabupaten Mahakam Ulu', 'pengumuman-hasil-3-tiga-calon-terbaik-seleksi-terbuka-pengisian-jabatan-pimpinan-tinggi-pratama-di-lingkungan-pemerintah-kabupaten-mahakam-ulu', '<p>Informasi selengkapnya dapat dilihat pada tautan di bawah ini :</p>\n<p>Pengumuman Nama 3 Besar SELTER JPTP Tahun 2026</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"Kepegawaian\",\"BeritaTerkini\"]', 'post', 1, 0, NULL, 148, 'Admin', '2026-08-22 00:00:00', 0, 166, '2026-09-02 08:13:54', '2026-10-30 17:34:22'),
(136, 1, 1, 'Siapkan SDM Pertanahan, Bupati Mahulu Dampingi Lima Taruna Asal Mahulu Di Politeknik Agraria STPN', 'siapkan-sdm-pertanahan-bupati-mahulu-dampingi-lima-taruna-asal-mahulu-di-politeknik-agraria-stpn', '<p>Yogyakarta – Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan, mendampingi lima taruna asal Mahulu dalam kegiatan Penyerahan Taruna Jalur Kerja Sama Politeknik Agraria Sekolah Tinggi Pertanahan Nasional (STPN) Tahun Akademik 2026/2027. Kegiatan berlangsung di Politeknik Agraria STPN, Sleman, Daerah Istimewa Yogyakarta, Jumat (21/08/2026).</p>\n<p>Kelima taruna tersebut terdiri atas dua laki-laki dan tiga perempuan. Mereka menjadi bagian dari 345 mahasiswa baru Politeknik Agraria STPN Tahun Akademik 2026/2027.</p>\n<p>Kehadiran lima taruna asal Mahulu menjadi bagian dari upaya Pemerintah Kabupaten Mahakam Ulu menyiapkan sumber daya manusia yang memiliki kompetensi di bidang pertanahan.</p>\n<p>Rombongan Pemerintah Kabupaten (Pemkab) Mahulu diterima oleh Pelaksana Tugas Direktur Politeknik Agraria STPN, Dr. Sri Yanti Achmad, A.Ptnh., S.H., M.Kn., bersama jajaran pengelola akademik dan kemahasiswaan.</p>\n<p>Dalam sambutannya, Bupati menyampaikan apresiasi kepada Kementerian Agraria dan Tata Ruang/Badan Pertanahan Nasional serta Politeknik Agraria STPN yang telah memberikan kesempatan kepada putra-putri Mahulu untuk menempuh pendidikan melalui jalur kerja sama.</p>\n<p>Kelima taruna tersebut telah melewati proses seleksi dan ujian. Bupati mengingatkan bahwa kesempatan menempuh pendidikan di Politeknik Agraria STPN merupakan capaian yang disertai tanggung jawab untuk menjaga nama baik keluarga dan daerah.</p>\n<p>“Kesempatan ini jangan hanya dipandang sebagai keberhasilan pribadi, tetapi juga sebagai tanggung jawab untuk membawa nama baik keluarga dan daerah,” ujar Bupati.</p>\n<p>Menurut Angela Idang Belawan, penyiapan sumber daya manusia di bidang pertanahan memiliki arti penting bagi Mahakam Ulu. Hingga saat ini, Kabupaten Mahakam Ulu belum memiliki Kantor Pertanahan sendiri sehingga pelayanan masih bergantung pada Kantor Pertanahan Kabupaten Kutai Barat.</p>\n<p>Kondisi tersebut menjadi salah satu tantangan dalam mendekatkan pelayanan pertanahan kepada masyarakat. Karena itu, Mahakam Ulu membutuhkan aparatur yang memiliki kompetensi dan pemahaman di bidang pertanahan.</p>\n<p>“Pemerintah Kabupaten Mahakam Ulu juga terus berharap agar ke depan kami dapat memiliki Kantor Pertanahan sendiri sehingga pelayanan pertanahan semakin dekat, mudah, dan cepat,” ucapnya.</p>\n<p>Dalam pertemuan tersebut, Pemkab Mahulu dan pihak Politeknik Agraria STPN turut membahas kebutuhan tenaga aparatur bidang pertanahan. Penyiapan sumber daya manusia melalui jalur pendidikan diharapkan dapat mendukung kesiapan daerah dalam meningkatkan pelayanan kepada masyarakat.</p>\n<p>Bupati juga menitipkan kelima taruna asal Mahulu kepada pimpinan dan jajaran Politeknik Agraria STPN agar mendapatkan pendidikan serta pembinaan yang baik selama menjalani perkuliahan.</p>\n<p>“Kepada Bapak dan Ibu pimpinan Kementerian ATR/BPN, kami titip anak-anak kami. Mohon dibimbing, dididik, dan dibina dengan sebaik-baiknya. Didik dan bentuk mereka menjadi tenaga yang kompeten, berintegritas, dan memiliki semangat pengabdian,” pesannya.</p>\n<p>Kepada kelima taruna, Angela Idang Belawan berpesan agar belajar dengan sungguh-sungguh, menjaga disiplin, serta membawa nama baik Kabupaten Mahakam Ulu selama menempuh pendidikan.</p>\n<p>Menutup sambutan dengan penuh haru, Bupati Angela menyampaikan rasa bangga dan keyakinannya terhadap kemampuan kelima taruna asal Mahulu tersebut.</p>\n<p>“Saya bangga dengan pencapaian kalian. Saya yakin kalian akan lulus dengan baik dan kembali ke Mahakam Ulu,” ungkapnya.</p>\n<p>Turut hadir dalam kegiatan tersebut Kepala Dinas Pendidikan dan Kebudayaan Kabupaten Mahakam Ulu, Samson Batang, S.Sos., M.Si., beserta jajaran serta Perancang Peraturan Perundang-undangan Ahli Muda pada Bagian Hukum, Fransiska W.L., S.H., M.Si. Hadir pula perwakilan Dinas Pemuda dan Olahraga Kabupaten Tabalong serta perwakilan Bagian Hukum Kabupaten Halmahera Tengah.</p>\n<p>Dari Politeknik Agraria STPN turut hadir Kepala Bagian Administrasi, Kepala Bagian Akademik, Ketua Program Studi, Pembantu Ketua Bidang Kemahasiswaan, Kepala Subbagian Kerja Sama, serta Kepala Sub Bagian Kemahasiswaan. (Prokopim)</p>\n<p>Berita TerkiniBidang Pemerintahan dan Kesejahteraan RakyatKerja SamaPendidikan</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangPemerintahandanKesejahteraanRakyat\"]', 'post', 1, 0, NULL, 127, 'Adm', '2026-08-21 00:00:00', 0, 167, '2026-09-02 08:13:54', '2026-10-30 05:01:35'),
(137, 1, 1, 'Paripurna Kesepakatan KUA dan PPAS TA 2027, Pemkab Mahulu Dorong APBD 2027 Pada Pelayanan, Pemerataan dan Kesejahteraan Masyarakat', 'paripurna-kesepakatan-kua-dan-ppas-ta-2027-pemkab-mahulu-dorong-apbd-2027-pada-pelayanan-pemerataan-dan-kesejahteraan-masyarakat', '<p>Samarinda – Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan, yang dalam kesempatan ini diwakili Wakil Bupati (Wabup) Mahulu, Suhuk, S.E., menghadiri Rapat Paripurna DPRD Kabupaten Mahakam Ulu dalam rangka kesepakatan bersama Kebijakan Umum Anggaran (KUA) dan Prioritas dan Plafon Anggaran Sementara (PPAS) APBD Kabupaten Mahakam Ulu Tahun Anggaran 2027, di Ballroom Lantai 17, Hotel Aston Samarinda. Jumat (21/08/2026)</p>\n<p>Dalam sambutan Bupati Mahulu yang disampaikan Wabup Suhuk, ditegaskan bahwa kesepakatan KUA dan PPAS bukan sekadar menyepakati angka-angka dalam dokumen anggaran, tetapi merupakan kesepakatan mengenai arah pembangunan Mahulu pada tahun 2027.</p>\n<p>“Kesepakatan yang kita capai pada hari ini bukan sekadar kesepakatan terhadap angka-angka anggaran, melainkan merupakan kesepakatan terhadap arah pembangunan Kabupaten Mahakam Ulu pada tahun 2027,” tegasnya.</p>\n<p>KUA dan PPAS APBD 2027 disusun dengan mempertimbangkan arah pembangunan dalam RPJMD Kabupaten Mahakam Ulu Tahun 2025–2029, prioritas pembangunan Pemerintah Provinsi Kalimantan Timur dan Pemerintah Pusat, kondisi fiskal daerah, perkembangan ekonomi makro, kemampuan riil keuangan daerah, evaluasi pelaksanaan APBD 2026 serta kebutuhan pembangunan dan pelayanan masyarakat.</p>\n<p>Berdasarkan proyeksi yang disusun, pendapatan daerah Tahun Anggaran 2027 direncanakan sekitar Rp1,256 triliun, sementara belanja daerah direncanakan sebesar Rp1,470 triliun. Adapun penerimaan pembiayaan daerah direncanakan sekitar Rp213,189 miliar.</p>\n<p>Dengan kondisi fiskal tersebut, Pemerintah Kabupaten Mahulu menekankan pentingnya kehati-hatian dan ketepatan dalam menentukan prioritas anggaran.</p>\n<p>“Setiap rupiah yang dialokasikan dalam APBD harus benar-benar diarahkan untuk program dan kegiatan yang memberikan manfaat sebesar-besarnya bagi masyarakat, mendukung pencapaian target pembangunan daerah, meningkatkan kualitas pelayanan publik, serta mempercepat pemerataan pembangunan di seluruh wilayah Kabupaten Mahakam Ulu,” tegas Wabup Suhuk membacakan sambutan Bupati.</p>\n<p>Ia menegaskan, keterbatasan kemampuan fiskal daerah tidak boleh menjadi alasan untuk menurunkan kualitas pelayanan kepada masyarakat. Sebaliknya, kondisi tersebut harus mendorong pemerintah daerah bekerja lebih efektif, efisien, inovatif, transparan dan akuntabel.</p>\n<p>“Kita harus memastikan bahwa keterbatasan kemampuan fiskal tidak mengurangi semangat kita untuk memberikan pelayanan terbaik kepada masyarakat. Justru kondisi tersebut harus mendorong kita untuk bekerja semakin efektif, efisien, inovatif, transparan dan akuntabel,” ujarnya.</p>\n<p>Dalam kesempatan tersebut, Pemerintah Kabupaten Mahulu juga memberikan apresiasi kepada pimpinan dan seluruh anggota DPRD, khususnya Badan Anggaran DPRD, bersama Tim Anggaran Pemerintah Daerah yang telah menjalani proses pembahasan KUA dan PPAS secara bersama-sama.</p>\n<p>Berbagai saran, masukan, koreksi dan pandangan DPRD, menurut pemerintah daerah, menjadi bagian penting dalam penyempurnaan kebijakan pembangunan dan penganggaran daerah. Kesepakatan yang dicapai juga mencerminkan kuatnya kemitraan antara pemerintah daerah dan DPRD dalam menjalankan amanat masyarakat.</p>\n<p>“Kita boleh memiliki sudut pandang yang berbeda dalam proses pembahasan, tetapi kita memiliki tujuan yang sama, yaitu menghadirkan pembangunan yang semakin merata, meningkatkan kualitas pelayanan publik, memperkuat perekonomian daerah, serta meningkatkan kesejahteraan seluruh masyarakat Kabupaten Mahakam Ulu,” ungkapnya.</p>\n<p>Setelah kesepakatan KUA dan PPAS ditandatangani, Wabup Suhuk meminta seluruh kepala perangkat daerah segera menindaklanjutinya dalam penyusunan Rencana Kerja dan Anggaran Perangkat Daerah.</p>\n<p>Penyusunan tersebut harus tetap berpedoman pada plafon anggaran, target kinerja, prioritas pembangunan serta seluruh catatan dan hasil pembahasan yang telah disepakati bersama.</p>\n<p>Yang menjadi perhatian khusus pemerintah daerah adalah memastikan APBD tidak hanya berorientasi pada penyerapan anggaran, tetapi pada hasil yang benar-benar dirasakan masyarakat.</p>\n<p>“Saya juga menegaskan agar penyusunan anggaran tidak hanya berorientasi pada penyerapan anggaran, tetapi harus berorientasi pada hasil dan manfaat yang dapat dirasakan secara nyata oleh masyarakat,” tegasnya.</p>\n<p>Karena itu, program pembangunan diarahkan semakin tepat sasaran dengan mengurangi kegiatan yang kurang memberikan dampak langsung, menghindari pemborosan serta memberikan perhatian sungguh-sungguh terhadap kebutuhan dasar masyarakat dan pembangunan yang menjadi prioritas Kabupaten Mahulu.</p>\n<p>“Mari kita jadikan APBD Tahun Anggaran 2027 sebagai instrumen pembangunan yang realistis, sehat, efektif, efisien, transparan, akuntabel, dan berpihak pada kepentingan masyarakat,” pungkasnya.</p>\n<p>Kesepakatan KUA dan PPAS Tahun Anggaran 2027 selanjutnya menjadi landasan untuk memasuki tahapan penyusunan dan pembahasan Rancangan APBD Kabupaten Mahakam Ulu Tahun Anggaran 2027.</p>\n<p>Pemerintah Kabupaten Mahulu berharap semangat kebersamaan, keterbukaan dan kemitraan antara pemerintah daerah dan DPRD terus dipertahankan dalam setiap tahapan penganggaran, sehingga APBD 2027 benar-benar menjadi instrumen pembangunan yang mampu menjawab kebutuhan masyarakat dan mendorong kemajuan Mahakam Ulu. (Prokopim/tha)</p>\n<p>Berita TerkiniBidang Ekonomi dan PembangunanParipurnaPembangunanPemerintahan</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangEkonomidanPembangunan\"]', 'post', 1, 0, NULL, 117, 'Adm', '2026-08-21 00:00:00', 0, 168, '2026-09-02 08:13:54', '2026-10-30 13:40:42'),
(138, 1, 1, 'Wakil Bupati Mahulu Hadiri Rapat Paripurna Kesepakatan KUA dan PPAS TA 2027', 'wakil-bupati-mahulu-hadiri-rapat-paripurna-kesepakatan-kua-dan-ppas-ta-2027', '<p>Samarinda – Mewakili Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan, Wakil Bupati (Wabup) Mahulu, Suhuk, S.E., menghadiri Rapat Paripurna Dewan Perwakilan Rakyat Daerah (DPRD) Kabupaten Mahakam Ulu dalam rangka Kesepakatan Kebijakan Umum Anggaran (KUA) dan Prioritas Plafon Anggaran Sementara (PPAS) Tahun Anggaran 2027, di Ballroom Lantai 17 Hotel Aston Samarinda. Jumat (21/08/2026)</p>\n<p>Rapat paripurna yang merupakan bagian penting dalam tahapan penyusunan Anggaran Pendapatan dan Belanja Daerah (APBD) Kabupaten Mahakam Ulu Tahun Anggaran 2027, dipimpin langsung oleh Ketua DPRD Mahulu, Devung Paran, A.Md, Keb., SH.</p>\n<p>Dalam Rapat paripurna ini, usai dibuka oleh pimpinan sidang, dilanjutkan dengan penyampaian laporan Badan Anggaran DPRD terhadap hasil pembahasan KUA dan PPAS Tahun Anggaran 2027. Kemudian dilanjutkan dengan penandatanganan Nota Kesepakatan KUA dan PPAS Tahun Anggaran 2027 serta pendapat akhir atau sambutan Bupati sebelum rapat ditutup.</p>\n<p>Rapat paripurna turut dihadiri, Wakil Ketua I DPRD Mahulu, Nor Lili Bulan dan anggota DPRD Mahulu, Sekretaris Daerah Mahulu, Dr. Stephanus Madang, S.Sos., M.M., Asisten Bidang Pemerintahan dan Kesejahteraan Rakyat Mahulu, drg. Agustinus Teguh Santoso, M.Adm., Kes., unsur Forum Koordinasi Pimpinan Daerah, perangkat daerah, serta sejumlah pemangku kepentingan terkait di Lingkup Pemerintahan Kabupaten Mahulu.</p>\n<p>Kesepakatan KUA dan PPAS Tahun Anggaran 2027 menjadi salah satu tahapan strategis dalam proses penyusunan APBD, sebagai landasan bagi pemerintah daerah dan DPRD dalam menetapkan arah kebijakan serta prioritas pembangunan daerah pada tahun anggaran mendatang. (Prokopim/tha)</p>\n<p>Berita TerkiniBidang Ekonomi dan PembangunanParipurnaPembangunanPemerintahan</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangEkonomidanPembangunan\"]', 'post', 1, 0, NULL, 126, 'Adm', '2026-08-21 00:00:00', 0, 169, '2026-09-02 08:13:54', '2026-10-29 21:50:57'),
(139, 1, 1, 'Pemkab Mahulu Matangkan Rumusan Tarif PLTS, Bupati Tegaskan Layanan Energi Harus Terjangkau dan Berkelanjutan', 'pemkab-mahulu-matangkan-rumusan-tarif-plts-bupati-tegaskan-layanan-energi-harus-terjangkau-dan-berkelanjutan', '<p>Samarinda – Pemerintah Kabupaten (Pemkab) Mahakam Ulu (Mahulu), terus memperkuat langkah strategis dalam memastikan ketersediaan energi listrik yang terjangkau, andal, dan berkelanjutan bagi masyarakat hingga ke kampung-kampung yang belum sepenuhnya terjangkau jaringan listrik konvensional.</p>\n<p>Komitmen tersebut didorong dalam Focus Group Discussion (FGD) Laporan Akhir Penyusunan Rumusan Tarif Layanan Energi Listrik Berbasis Pembangkit Listrik Tenaga Surya (PLTS) Kabupaten Mahakam Ulu, yang dilaksanakan di Hotel Fugo Samarinda. Kamis (20/8/2026)</p>\n<p>Bupati Mahulu, Angela Idang Belawan, dalam kegiatan tersebut diwakili Sekretaris Daerah Kabupaten Mahulu, Dr. Stephanus Madang, S.Sos., M.M., menegaskan bahwa penyusunan rumusan tarif tidak semata-mata berbicara mengenai besaran biaya layanan, tetapi harus menjadi bagian dari upaya memastikan PLTS dapat dikelola secara berkelanjutan dan benar-benar memberikan manfaat bagi masyarakat.</p>\n<p>Dalam sambutan Bupati yang dibacakan Sekda, disebutkan bahwa energi listrik merupakan kebutuhan dasar sekaligus salah satu fondasi pembangunan daerah karena berperan penting dalam mendukung pendidikan, pelayanan kesehatan, komunikasi, kegiatan ekonomi hingga pelayanan pemerintahan.</p>\n<p>“Tarif yang kita rumuskan harus mencerminkan kondisi masyarakat dan sistem PLTS di Mahakam Ulu. Pengalaman pengguna dan kondisi fasilitas harus menjadi bagian dari kajian. Kemampuan pengelola serta kebutuhan biaya operasional juga perlu diperhitungkan,” demikian penegasan Bupati dalam sambutannya.</p>\n<p>Menurutnya, kondisi geografis Mahulu dengan wilayah yang luas dan keterbatasan akses transportasi menjadi tantangan tersendiri dalam memperluas jaringan listrik konvensional. Karena itu, pengembangan PLTS menjadi salah satu solusi yang relevan untuk memenuhi kebutuhan listrik masyarakat di wilayah yang belum terjangkau jaringan konvensional.</p>\n<p>FGD tersebut menjadi ruang penting untuk menguji sekaligus menyempurnakan hasil kajian agar rumusan tarif yang dihasilkan benar-benar berpijak pada kondisi faktual di lapangan. Pemkab Mahulu berharap kajian pada PLTS Batoq Kelo, Matalibaq, Wana Pariq, dan Tri Pariq Makmur dapat memberikan gambaran yang objektif dan representatif sebagai dasar perumusan kebijakan layanan PLTS ke depan.</p>\n<p>Bupati juga menekankan pentingnya keterlibatan seluruh pihak dalam memberikan data dan informasi berdasarkan pengalaman pengelolaan PLTS. Rumusan yang dihasilkan harus bermuara pada satu kepentingan bersama, yakni menghadirkan layanan energi listrik yang bermutu dan dapat diandalkan bagi masyarakat Mahulu.</p>\n<p>Selain aspek tarif, kajian tersebut juga diarahkan untuk memperjelas kelembagaan pengelola, mekanisme pemungutan tarif, pembagian peran, serta pembiayaan pemeliharaan. Kejelasan aspek tersebut dinilai penting agar pengelolaan PLTS dapat berjalan secara tertib, transparan, dan dapat dipertanggungjawabkan.</p>\n<p>“PLTS harus menjadi aset yang produktif dan terawat agar dapat melayani masyarakat dalam jangka panjang,” tegas Bupati.</p>\n<p>Pemkab Mahulu, lanjutnya berkomitmen memastikan manfaat pembangunan dapat dirasakan secara merata hingga kampung-kampung yang jauh dari pusat pemerintahan. Ketersediaan energi listrik yang andal bukan hanya menyangkut penerangan, tetapi juga membuka ruang yang lebih besar bagi peningkatan kualitas pendidikan, pelayanan kesehatan, komunikasi, pertumbuhan ekonomi dan kesejahteraan masyarakat.</p>\n<p>Pada kesempatan tersebut, Pemkab Mahulu juga menyampaikan apresiasi kepada Bagian Perekonomian dan Sumber Daya Alam Sekretariat Daerah Kabupaten Mahulu, tim tenaga ahli, perangkat daerah terkait, pemerintah kecamatan dan kampung, serta para operator PLTS yang telah mendukung proses penyusunan kajian hingga tahap laporan akhir.</p>\n<p>Melalui FGD ini, Pemkab Mahulu berharap rumusan tarif yang dihasilkan mampu menemukan titik keseimbangan antara keterjangkauan bagi masyarakat dan keberlanjutan pengelolaan layanan. Dengan demikian, pembangunan PLTS tidak berhenti pada penyediaan infrastruktur, tetapi memastikan infrastruktur tersebut terus berfungsi dan memberi manfaat nyata bagi masyarakat dalam jangka panjang.</p>\n<p>“Keberhasilan pembangunan diukur dari kemampuan infrastruktur untuk terus memberi manfaat bagi masyarakat. Karena itu, keberlangsungan layanan PLTS harus menjadi tanggung jawab kita bersama,” tegasnya.</p>\n<p>Pemkab Mahulu menegaskan, penguatan energi berbasis PLTS merupakan bagian dari ikhtiar membangun sistem energi yang mandiri, berkeadilan, dan berkelanjutan, sekaligus memperkuat pemerataan pembangunan hingga ke seluruh wilayah Mahakam Ulu.</p>\n<p>Hadir dalam kegiatan ini Tim TP3D Mahulu, OPD terkait yakni Bappenda, DLH, DPMPTSP, Dinas PUPR, Bagian Kesra, Bagian Hukum, Bagian EkoSDA, dan Camat Long Hubung. Kemudian Petinggi dan BPK dari Kampung Batoq Kelo, Kampung Matalibaq, Kampung Wana Pariq, dan Kampung Tri Pariq Makmur. Turut hadir pula Operator PLTS dari Matalibaq dan Wana Pariq. Tenaga Ahli Penyusun Rumus Tarif Layanan Energi Listrik Berbasis PLTS Kabupaten Mahulu.</p>\n<p>Pada kesempatan ini hadir Kepala Laboratorium Konversi Energi Elektrik Teknik Elektro, ITN Malang, Dr. Ir. Widodo Pudji Muljanto, MT, selaku ketua Tim dari ITN Malang bersama anggota. (Prokopim/tha)</p>\n<p>Berita TerkiniBidang Ekonomi dan PembangunanPelayananPembangunan</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangEkonomidanPembangunan\"]', 'post', 1, 0, NULL, 145, 'Adm', '2026-08-20 00:00:00', 0, 170, '2026-09-02 08:13:54', '2026-10-29 21:52:51'),
(140, 1, 1, '9,7 Ton Bantuan Pangan Tiba, Pemkab Mahulu Bergerak Jaga Kebutuhan Masyarakat Di Tengah Kemarau', '97-ton-bantuan-pangan-tiba-pemkab-mahulu-bergerak-jaga-kebutuhan-masyarakat-di-tengah-kemarau', '<p>Ujoh Bilang – Bupati Mahakam Ulu (Mahulu), Angela Idang Belawan didampingi Wakil Bupati Mahulu, Suhuk, S.E., menerima sebanyak 9,7 ton bantuan cadangan pangan, bahan pokok penting, dan energi (LPG serta bahan bakar) pada Rabu (19/8/2026) sore.</p>\n<p>Bantuan tersebut merupakan bagian dari upaya Pemerintah Provinsi (Pemprov) Kalimantan Timur (Kaltim) dan Pemerintah Kabupaten (Pemkab) Mahulu dalam menjaga ketersediaan kebutuhan pokok masyarakat di tengah kondisi kemarau yang berdampak terhadap distribusi barang ke wilayah hulu Mahakam.</p>\n<p>Bupati Angela Idang Belawan mengatakan, bantuan tersebut akan disalurkan melalui skema Gerakan Pangan Murah (GPM) dan Operasi Pasar Murah (OPM). Untuk tahap awal, GPM dari Dinas Ketahanan Pangan dan Pertanian (DKPP) akan diarahkan ke Long Pahangai, sedangkan OPM dari Bagian Ekonomi dan Sumber Daya Alam (EkoSDA) dijadwalkan menyasar Long Apari sekitar 24 Agustus.</p>\n<p>“Yang sudah sampai hari ini sebanyak 9,7 ton. Ini akan kita bawa ke Long Apari dan Long Pahangai. Kita bersyukur karena sudah ada sembako yang bisa kita kerahkan ke Long Pahangai maupun ke Long Apari,” kata Angela usai menerima bantuan.</p>\n<p>Menurutnya, bantuan yang tiba tersebut belum merupakan keseluruhan bantuan pangan yang akan diterima Mahulu. DKPP masih mengirimkan sekitar tujuh ton bantuan yang diperkirakan tiba pada malam hari, sehingga total bantuan pangan yang akan dikerahkan mencapai lebih dari 16 ton.</p>\n<p>“Tidak hanya 9,7 ton ini. Ada dari DKPP sekitar tujuh ton, jadi totalnya sekitar 16 sekian ton dan akan langsung disalurkan ke Long Pahangai. Sedangkan dari EkoSDA akan dibawa ke Long Apari. Kita akan berbagi,” jelas Angela.</p>\n<p>Angela menjelaskan, salah satu kendala utama dalam pengiriman bantuan dari pemerintah provinsi saat ini adalah biaya angkutan. Karena itu, Pemkab Mahulu akan mengupayakan penggunaan armada pemerintah daerah maupun menanggung biaya angkut agar distribusi bantuan tidak terhambat.</p>\n<p>“Bagaimanapun caranya yang penting tercukupi sembako yang ada di Long Apari, Long Pahangai, bahkan di tiga kecamatan yang di hilir ini. Entah nanti dengan armada kita sendiri ataupun dengan ongkos angkut yang kita bebankan ke Pemda. Setidaknya provinsi sudah membantu kita dengan barangnya, bahan sembakonya,” katanya.</p>\n<p>Bantuan dari Pemerintah Provinsi Kalimantan Timur tersebut dikirim dari Samarinda menuju Long Bagun. Selain pangan, bantuan juga mencakup LPG untuk menjaga ketersediaan energi rumah tangga di tengah terganggunya distribusi akibat kondisi kemarau dan surutnya Sungai Mahakam.</p>\n<p>Pertamina Patra Niaga melalui mitra penyalur atau agen LPG mengirimkan 720 tabung LPG 3 kilogram serta 200 tabung Bright Gas 12 kilogram. Sementara bantuan pangan terdiri atas 330 sak beras Premium Kita kemasan 5 kilogram, 600 pcs Minyakita kemasan 2 liter, dan 1.200 pcs gula Rose Brand kemasan 1 kilogram.</p>\n<p>Bantuan tersebut sekaligus dirangkaikan dengan operasi pasar untuk menjaga ketersediaan pasokan sekaligus membantu mengendalikan harga kebutuhan pokok yang terdampak kendala distribusi.</p>\n<p>Di tengah kondisi distribusi yang masih mahal, Pemkab Mahulu juga menyiapkan langkah melalui pemanfaatan Belanja Tidak Terduga (BTT). Namun, Angela menegaskan BTT tidak sepenuhnya diarahkan untuk pembelian sembako, melainkan diprioritaskan untuk memperbaiki akses jalan Long Pakaq menuju Tiong Ohang yang saat ini mengalami banyak titik putus.</p>\n<p>“Untuk BTT Mahulu kita lebih mengutamakan untuk jalan dari Long Pakaq ke Tiong Ohang karena kondisi jalan di sana banyak yang terputus. Itu yang mau kita kerjakan supaya jalan Long Pakaq dan Tiong Ohang bisa punya kondisi yang lebih baik dan bisa tembus menggunakan mobil,” jelasnya.</p>\n<p>Menurut Angela, pembukaan akses darat tersebut diharapkan dapat menekan biaya distribusi barang ke wilayah hulu. Selama ini, pengangkutan melalui sungai membutuhkan biaya besar sehingga turut mempengaruhi harga kebutuhan pokok masyarakat.</p>\n<p>Berdasarkan laporan Camat Long Apari Petrus Ngo, tarif angkutan menggunakan perahu ketinting dari Long Lunuk menuju sejumlah wilayah mencapai jutaan rupiah per perjalanan. Untuk rute Long Lunuk–Tiong Ohang, tarif angkutan mencapai Rp2,75 juta per perahu, ditambah BBM 25 liter. Sementara rute Long Lunuk–Noha Silat mencapai Rp 4,25 juta ditambah 45 liter BBM, dan Long Lunuk–Long Apari/Noha Tivab mencapai Rp5,55 juta ditambah 65 liter BBM.</p>\n<p>“Harapan kita dengan pembukaan jalan ini akan menekan harga, karena ongkos angkut lebih murah daripada sebelumnya. Kita tahu sendiri ongkos angkut lewat sungai lebih tinggi daripada lewat darat,” kata Angela.</p>\n<p>Pemkab Mahulu selanjutnya akan membawa kebutuhan peningkatan akses tersebut kepada pemerintah provinsi maupun pemerintah pusat agar pembangunan infrastruktur dapat terus dilanjutkan. Langkah tersebut diharapkan dapat memperkuat konektivitas sekaligus mengurangi beban biaya distribusi ke wilayah hulu.</p>\n<p>Selain kebutuhan pangan dan infrastruktur, Pemkab Mahulu juga akan memetakan kebutuhan kelompok masyarakat yang dinilai rentan selama kondisi kemarau dan gangguan distribusi. Obat-obatan serta kebutuhan balita, bayi, ibu hamil, lansia dan masyarakat yang sedang sakit akan menjadi perhatian khusus pemerintah daerah.</p>\n<p>“Tidak hanya masyarakat umum, tapi yang spesial seperti ibu hamil, balita, bayi, lansia dan orang sakit juga perlu kita utamakan,” ujarnya.</p>\n<p>Selanjutnya, seluruh organisasi perangkat daerah (OPD) terkait diminta menyusun kebutuhan berdasarkan data di lapangan agar penanganan yang dilakukan pemerintah benar-benar sesuai dengan kondisi masyarakat. (Prokopim)</p>\n<p>Berita TerkiniBidang Ekonomi dan PembangunanKetahanan PanganPenanggulangan Bencana</p>', NULL, NULL, '[\"PressRelease\",\"Pembangunan\",\"Pemerintahan\",\"Ekonomi\",\"Kesehatan\",\"Pendidikan\",\"Pertanian\",\"Sosial\",\"Pariwisata\",\"Pengumuman\",\"BeritaTerkini\",\"BidangEkonomidanPembangunan\"]', 'post', 1, 0, NULL, 146, 'Adm', '2026-08-19 00:00:00', 0, 171, '2026-09-02 08:13:54', '2026-10-30 08:47:47');
