INSERT INTO `ppid_abouts` (`id`, `profil`, `visi`, `misi`, `maklumat`, `content`, `created_at`, `updated_at`) VALUES
(1, 'Informasi Berkala\n \n \n\n \n \n Informasi Serta Merta\n \n \n\n \n \n Informasi Dikecualikan\n \n \n\n \n \n Informasi Setiap Saat\n \n \n\n \n \n\n \n \n \n\n \n\n \n\n \n\n \n\n \n \n \n BERANDA\n \n \n \n\n PPID \\\n Tentang PPID \n \n\n \n\n \n \n \n Tentang PPID\n \n\n \n PEJABAT PENGELOLA INFORMASI DAN DOKUMENTASI\n\nPemerintah Indonesia telah melakukan sebuah langkah besar dalam upaya reformasi birokrasi dan penyelenggaraan pemerintahan yang lebih transparan dengan pengesahan Undang-undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik (UU KIP). Undang-undang tersebut dengan tegas memberikan kewajiban kepada setiap badan/institusi publik untuk membuka informasi mengenai institusinya kepada masyarakat. Dengan adanya keterbukaan informasi ini, masyarakat dapat ikut mengawal badan/institusi publik dalam menjalankan tugas dan fungsinya serta memberikan pelayanan publik yang prima, transparan, dan akuntabel.\n\nDalam rangka menjalankan amanat UU KIP dan memberikan pelayanan publik yang berkualitas, Inspektorat Daerah Kabupaten Mahakam Ulu, sebagai salah satu badan/institusi publik, menunjuk Pejabat Pengelola Informasi dan Dokumentasi (PPID) untuk menyediakan sistem pelayanan informasi publik yang mudah, cepat, dan akurat serta sesuai dengan standar pelayanan yang telah ditetapkan. Inspektorat Daerah Kabupaten Mahakam Ulu memandang bahwa penunjukan PPID bukan sekedar upaya memenuhi kewajiban UU KIP, namun lebih dari itu keterbukaan informasi merupakan salah satu komponen penting dalam peningkatan kualitas pembangunan terutama dari sisi evaluasi dan pengawasan. Dengan PPID Inspektorat Daerah Kabupaten Mahakam Ulu, masyarakat dapat memperoleh berbagai informasi mengenai Inspektorat Daerah Kabupaten Mahakam Ulu dengan lebih mudah, cepat dan akurat. Pada akhirnya, dapat meningkatkan partisipasi aktif masyarakat dalam menyukseskan pembangunan di Kabupaten Mahakam Ulu. \n\n \n\n \n \n \n\n \n ×\n\n \n \n\n \n \n \n \n \n \n \n BAPPELITBANGDA\nKab MAHULU\n\n \n\n \n\n \n \n \n \n Komplek Perkantoran Semi Permanen Ujoh Bilang\n\n \n\n \n \n \n \n\n 0853-4559-2345\n\n \n\n \n \n \n \n\n -@gmail.com\n\n \n\n \n \n \n \n\n bappelitbangdamahulu\n\n \n \n \n \n \n\n BAPPELITBANGDA Kab MAHULU', NULL, NULL, NULL, NULL, '2026-05-10 00:56:45', '2026-05-10 00:56:45');

